            Add("achievements:ach_char_robin",
                "ЗОЛОТАЯ ЛЕТОПИСЬ ГАРМОНИИ // СЮЖЕТНОЕ ИСПЫТАНИЕ — ПУСТЬ НЕ УМОЛКНЕТ ПЕСНЯ ГАРМОНИИ",
